@dataclass
class Style:
    background: str = "white"
    fill_color: str = "black"
    stroke_color: str = "black"
    font_family: str = "Iosevka Fixed, monospace"
    font_size: str = "14"
    stroke_width: str = "2"
    scale: float = 1.0

@dataclass
class Element:
    key: tuple
    text: str


def fmt_num(v):
    """Format numeric SVG attributes like Rust's Display for ordinary floats."""
    try:
        f = float(v)
    except Exception:
        return str(v)
    if abs(f) < 1e-12:
        f = 0.0
    if abs(f - round(f)) < 1e-9:
        return str(int(round(f)))
    s = ("%.12g" % f)
    # Avoid scientific notation for normal small diagram values where Rust prints decimals.
    if "e" in s or "E" in s:
        s = ("%.12f" % f).rstrip("0").rstrip(".")
    return s


def esc_text(s):
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;")
             .replace('"', "&quot;")
             .replace("'", "&#39;"))


def norm_input(data):
    # Rust's lines-style processing ignores trailing line terminators/blank rows for layout.
    data = data.replace("\r\n", "\n").replace("\r", "\n")
    parts = data.split("\n")
    # If input ended in a newline, split() leaves an empty final line; svgbob ignores trailing blanks.
    while parts and parts[-1] == "":
        parts.pop()
    if not parts:
        parts = [""]
    # Trailing spaces do not contribute to dimensions or text, leading spaces do.
    return [p.rstrip(" \t") for p in parts]


def ch_at(grid, r, c):
    if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[r]):
        return " "
    return grid[r][c]


def scaled(style, x):
    return fmt_num(float(x) * style.scale)


def style_block(style: Style):
    return f"""  <style>.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {{
  stroke: {style.stroke_color};
  stroke-width: {style.stroke_width};
  stroke-opacity: 1;
  fill-opacity: 1;
  stroke-linecap: round;
  stroke-linejoin: miter;
}}

.svgbob text {{
