}}

.svgbob .end_marked_diamond {{
  marker-end: url(#diamond);
}}

.svgbob .start_marked_diamond {{
  marker-start: url(#diamond);
}}

.svgbob .end_marked_circle {{
  marker-end: url(#circle);
}}

.svgbob .start_marked_circle {{
  marker-start: url(#circle);
}}

.svgbob .end_marked_open_circle {{
  marker-end: url(#open_circle);
}}

.svgbob .start_marked_open_circle {{
  marker-start: url(#open_circle);
}}

.svgbob .end_marked_big_open_circle {{
  marker-end: url(#big_open_circle);
}}

.svgbob .start_marked_big_open_circle {{
  marker-start: url(#big_open_circle);
}}

</style>"""

DEFS = """  <defs>
    <marker id="arrow" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,0 0,4 4,2 0,0"></polygon>
    </marker>
    <marker id="diamond" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,2 2,0 4,2 2,4 0,2"></polygon>
    </marker>
    <marker id="circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="filled"></circle>
    </marker>
    <marker id="open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="bg_filled"></circle>
    </marker>
    <marker id="big_open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="3" class="bg_filled"></circle>
    </marker>
  </defs>"""


def line_el(style, x1, y1, x2, y2, cls="solid", indent="  "):
    return f'{indent}<line x1="{scaled(style,x1)}" y1="{scaled(style,y1)}" x2="{scaled(style,x2)}" y2="{scaled(style,y2)}" class="{cls}"></line>'


def rect_el(style, x, y, w, h, cls="solid nofill", rx=0, indent="  "):
    return f'{indent}<rect x="{scaled(style,x)}" y="{scaled(style,y)}" width="{scaled(style,w)}" height="{scaled(style,h)}" class="{cls}" rx="{scaled(style,rx)}"></rect>'


def polygon_arrow_left(style, c, r):
    y = r*16 + 8
    pts = [( (c+1)*8, y-4), (c*8, y), ((c+1)*8, y+4)]
    p = " ".join(f"{scaled(style,x)},{scaled(style,y)}" for x,y in pts)
    return f'  <polygon points="{p}" class="filled"></polygon>'


def polygon_arrow_right(style, c, r):
    y = r*16 + 8
    pts = [(c*8, y-4), ((c+1)*8, y), (c*8, y+4)]
    p = " ".join(f"{scaled(style,x)},{scaled(style,y)}" for x,y in pts)
    return f'  <polygon points="{p}" class="filled"></polygon>'


def path_el(style, d, indent="  "):
    # d already contains unscaled numbers. Scale each coordinate-ish number conservatively.
    # For arcs produced by this clone, build the scaled d directly in callers where needed.
    return f'{indent}<path d="{d}" class="nofill"></path>'


def marker_class(ch):
    if ch == 'o':
        return "end_marked_open_circle"
    if ch == 'O':
        return "end_marked_big_open_circle"
    if ch == '*':
        return "end_marked_circle"
    return None


def provides_h(ch):
    return ch in "-_=+<>oO*"


def provides_v(ch):
    return ch in "|+"


def merge_segments(segs):
    # segs: (a,b,key) where a,b numeric along same axis. Merge overlapping/adjacent.
    if not segs:
        return []
    segs = sorted((min(a,b), max(a,b), key) for a,b,key in segs)
    out = []
    ca, cb, ck = segs[0]
    for a,b,key in segs[1:]:
        if a <= cb + 1e-9:
            if b > cb:
                cb = b
            ck = min(ck, key)
        else:
            out.append((ca, cb, ck))
            ca, cb, ck = a,b,key
    out.append((ca, cb, ck))
    return out


def detect_rectangles(grid, style, consumed_text):
    rows = len(grid)
    rects = []
    occupied_perim = set()
    corner_sets = [('+','+','+','+',0), ('.','.','\'','\'',4), (',','.','`','\'',4)]
    # More permissive rounded: top .--. or ,--. and any quote/backtick lower corners.
    for r1 in range(rows):
        line = grid[r1]
        for c1,ch in enumerate(line):
            for c2 in range(c1+2, len(line)):
                top_l = ch
                top_r = ch_at(grid,r1,c2)
                # Decide possible rectangle flavor.
                rx = None
                if top_l == '+' and top_r == '+':
                    rx = 0
                elif top_l in '.,' and top_r == '.':
                    rx = 4
                else:
                    continue
                # Top horizontal must be dashes only.
                if any(ch_at(grid,r1,c) != '-' for c in range(c1+1,c2)):
                    continue
                for r2 in range(r1+2, rows):
                    bot_l = ch_at(grid,r2,c1)
                    bot_r = ch_at(grid,r2,c2)
                    if rx == 0:
                        if not (bot_l == '+' and bot_r == '+'):
                            continue
                    else:
                        if bot_l not in "'`" or bot_r != "'":
                            continue
                    if any(ch_at(grid,r2,c) != '-' for c in range(c1+1,c2)):
                        continue
                    ok = True
                    for rr in range(r1+1,r2):
                        if ch_at(grid,rr,c1) != '|' or ch_at(grid,rr,c2) != '|':
                            ok = False; break
                    if not ok:
                        continue
                    perim = set()
                    for c in range(c1,c2+1):
                        perim.add((r1,c)); perim.add((r2,c))
                    for rr in range(r1,r2+1):
                        perim.add((rr,c1)); perim.add((rr,c2))
                    if perim & occupied_perim:
                        continue
                    occupied_perim |= perim
                    consumed_text.update(perim)
                    x = c1*8 + 4; y = r1*16 + 8
                    w = (c2-c1)*8; h = (r2-r1)*16
                    rects.append(Element((r1,c1,0), rect_el(style,x,y,w,h,"solid nofill",rx)))
                    break
    return rects, occupied_perim


def render_svg(data, style=None):
    if style is None:
        style = Style()
    grid = norm_input(data)
    rows = max(1, len(grid))
    cols = max(1, max((len(x) for x in grid), default=0))
    width = (cols + 1) * 8
    height = (rows + 1) * 16

    consumed_text = set()
    elements = []

    rects, rect_perim = detect_rectangles(grid, style, consumed_text)
    elements.extend(rects)

    # Filled blocks (#), with vertical links between adjacent filled cells as observed.
    for r,line in enumerate(grid):
        for c,ch in enumerate(line):
            if ch == '#':
                consumed_text.add((r,c))
                elements.append(Element((r,c,1), rect_el(style,c*8,r*16+4,8,8,"solid filled",0)))
                if ch_at(grid,r+1,c) == '#':
                    elements.append(Element((r,c,2), line_el(style,c*8+4,r*16+12,c*8+4,(r+1)*16+4,"solid")))

    # Horizontal runs: -, _, =, with arrows/markers/plus endpoints.
    h_consumed = set()
    for r,line in enumerate(grid):
        c = 0
        n = len(line)
        while c < n:
            if (r,c) in rect_perim or (r,c) in h_consumed:
                c += 1; continue
            ch = line[c]
            # Runs may begin with marker or left arrow followed by dash, or with dash/equal/underscore.
            start_marker = None; left_arrow = False; run_char = None; start_c = c
            dash_start = c
            if ch in 'oO*' and ch_at(grid,r,c+1) == '-':
                start_marker = ch; consumed_text.add((r,c)); h_consumed.add((r,c)); dash_start = c+1; run_char='-'
            elif ch == '<' and ch_at(grid,r,c+1) == '-':
                left_arrow = True; consumed_text.add((r,c)); h_consumed.add((r,c)); dash_start = c+1; run_char='-'
                elements.append(Element((r,c,1), polygon_arrow_left(style,c,r)))
            elif ch in '-_=':
                run_char = ch; dash_start = c
            else:
                c += 1; continue
            # collect a homogeneous run of -, _, or =
            j = dash_start
            while ch_at(grid,r,j) == run_char and (r,j) not in rect_perim:
                h_consumed.add((r,j)); consumed_text.add((r,j)); j += 1
            if j == dash_start:
                c += 1; continue
            right_arrow = False; right_marker = None; right_c = None
            if run_char == '-' and ch_at(grid,r,j) == '>':
                right_arrow = True; right_c = j; consumed_text.add((r,j)); h_consumed.add((r,j))
            elif run_char == '-' and ch_at(grid,r,j) in 'oO*':
                right_marker = ch_at(grid,r,j); right_c = j; consumed_text.add((r,j)); h_consumed.add((r,j))
            # Include plus endpoints as line connectors, but leave them available for vertical rendering.
            left_plus = (dash_start-1 >= 0 and ch_at(grid,r,dash_start-1) == '+' and (r,dash_start-1) not in rect_perim)
            right_plus = (ch_at(grid,r,j) == '+' and (r,j) not in rect_perim)
            y = r*16 + (16 if run_char == '_' else 8)
            if run_char == '=':
                # equals produces two parallel lines
                x1 = dash_start*8
                x2 = j*8
                if left_plus: x1 = (dash_start-1)*8 + 4; consumed_text.add((r,dash_start-1))
                if right_plus: x2 = j*8 + 4; consumed_text.add((r,j))
                elements.append(Element((r,dash_start,3), line_el(style,x1,r*16+6,x2,r*16+6,"solid")))
                elements.append(Element((r,dash_start,4), line_el(style,x1,r*16+10,x2,r*16+10,"solid")))
            else:
                if start_marker:
                    center = start_c*8 + 4
                    if start_marker in 'oO':
                        rest_start = (start_c + 2) * 8
                    else:
                        rest_start = start_c*8 + 4
                    cls = "solid " + marker_class(start_marker)
                    elements.append(Element((r,start_c,1), line_el(style,rest_start,r*16+8,center,r*16+8,cls)))
                    plain_start = rest_start if start_marker in 'oO' else (start_c+1)*8
                elif left_arrow:
                    plain_start = (start_c+1)*8
                else:
                    plain_start = dash_start*8
                    if left_plus:
                        plain_start = (dash_start-1)*8 + 4; consumed_text.add((r,dash_start-1))
                if right_arrow:
                    plain_end = right_c*8
                    if plain_end != plain_start:
                        elements.append(Element((r,dash_start,3), line_el(style,plain_start,y,plain_end,y,"solid")))
                    elements.append(Element((r,right_c,5), polygon_arrow_right(style,right_c,r)))
                    c = right_c + 1
                    continue
                elif right_marker:
                    end = right_c*8 + 4
                    cls = "solid " + marker_class(right_marker)
                    # Match svgbob's short o-o quirk: no second marker line for a one-dash o/O-to-o/O run.
                    dash_count = j - dash_start
                    if not (start_marker in 'oO' and right_marker in 'oO' and dash_count <= 1):
                        if end != plain_start or right_marker:
                            elements.append(Element((r,dash_start,3), line_el(style,plain_start,y,end,y,cls)))
                    if start_marker == '*' and right_marker == '*':
                        # The original leaves a small solid tail near filled-circle ends.
                        elements.append(Element((r,right_c,4), line_el(style,right_c*8,y,right_c*8+4,y,"solid")))
                    c = right_c + 1
                    continue
                else:
                    plain_end = j*8
                    if right_plus:
                        plain_end = j*8 + 4; consumed_text.add((r,j))
                    if plain_end != plain_start or run_char in '-_':
                        elements.append(Element((r,dash_start,3), line_el(style,plain_start,y,plain_end,y,"solid")))
            c = max(j, c+1)

    # Vertical segments from | and + junctions. Build and merge by x coordinate.
    v_by_x = {}
    for r,line in enumerate(grid):
        for c,ch in enumerate(line):
            if (r,c) in rect_perim:
                continue
            x = c*8 + 4
            if ch == '|':
                consumed_text.add((r,c))
                v_by_x.setdefault(x, []).append((r*16, (r+1)*16, (r,c,2)))
            elif ch == '+':
                up = provides_v(ch_at(grid,r-1,c))
                down = provides_v(ch_at(grid,r+1,c))
                if up or down:
                    consumed_text.add((r,c))
                if up:
                    v_by_x.setdefault(x, []).append((r*16, r*16+8, (r,c,2)))
                if down:
                    v_by_x.setdefault(x, []).append((r*16+8, (r+1)*16, (r,c,2)))
    for x,segs in v_by_x.items():
        for a,b,key in merge_segments(segs):
            elements.append(Element(key, line_el(style,x,a,x,b,"solid")))

    # Diagonal slashes and backslashes.
    for r,line in enumerate(grid):
        for c,ch in enumerate(line):
            if (r,c) in rect_perim:
                continue
            if ch == '/':
                consumed_text.add((r,c))
                elements.append(Element((r,c,3), line_el(style,(c+1)*8,r*16,c*8,(r+1)*16,"solid")))
            elif ch == '\\':
                consumed_text.add((r,c))
                elements.append(Element((r,c,3), line_el(style,c*8,r*16,(c+1)*8,(r+1)*16,"solid")))

    # Parenthesis arcs.
    for r,line in enumerate(grid):
        for c,ch in enumerate(line):
            if (r,c) in rect_perim:
                continue
            if ch == '(':
                consumed_text.add((r,c))
                x = (c+1)*8; y0 = r*16; y1 = (r+1)*16
                d = f'M {scaled(style,x)},{scaled(style,y0)} A {scaled(style,16)},{scaled(style,16)} 0,0,0 {scaled(style,x)},{scaled(style,y1)}'
                elements.append(Element((r,c,2), f'  <path d="{d}" class="nofill"></path>'))
            elif ch == ')':
                consumed_text.add((r,c))
                x = c*8; y0 = r*16; y1 = (r+1)*16
                d = f'M {scaled(style,x)},{scaled(style,y0)} A {scaled(style,16)},{scaled(style,16)} 0,0,1 {scaled(style,x)},{scaled(style,y1)}'
                elements.append(Element((r,c,2), f'  <path d="{d}" class="nofill"></path>'))

    # Remaining text, grouped horizontally through non-space characters.
    for r,line in enumerate(grid):
        c = 0
        while c < len(line):
            if (r,c) in consumed_text or line[c] in ' \t':
                c += 1; continue
            start = c
            chars = []
            while c < len(line) and (r,c) not in consumed_text and line[c] not in ' \t':
                chars.append(line[c]); c += 1
            if chars:
                txt = esc_text("".join(chars))
                x = start*8 + 2; y = r*16 + 12
                elements.append(Element((r,start,9), f'  <text x="{scaled(style,x)}" y="{scaled(style,y)}" >{txt}</text>'))

    elements.sort(key=lambda e: e.key)

    sw = fmt_num(width * style.scale)
    sh = fmt_num(height * style.scale)
    out = []
    out.append(f'<svg xmlns="http://www.w3.org/2000/svg" width="{sw}" height="{sh}" class="svgbob">')
    out.append(style_block(style))
    out.append(DEFS)
    out.append(f'  <rect class="backdrop" x="0" y="0" width="{sw}" height="{sh}"></rect>')
    out.extend(e.text for e in elements)
    out.append('</svg>')
    return "\n".join(out) + "\n"


def clap_unexpected(arg, usage="executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]"):
    sys.stderr.write(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\n")
    sys.stderr.write(f"USAGE:\n    {usage}\n\nFor more information try --help\n")
    return 1


def missing_value(opt):
    sys.stderr.write(f"error: The argument '{opt} <{opt.lstrip('-')}>' requires a value but none was supplied\n\n")
    sys.stderr.write(f"USAGE:\n    executable {opt} <{opt.lstrip('-')}>\n\nFor more information try --help\n")
    return 1


def parse_float_value(name, value):
    try:
        return float(value)
    except Exception:
        sys.stderr.write(f"Illegal value for argument {name}: invalid float literal\n")
        raise SystemExit(1)


def parse_font_size(value):
    if not value.isdigit():
        # Rust's parse::<usize> gives this for alphabetic/decimal inputs; clap handles - separately.
        sys.stderr.write("Illegal value for argument font-size: invalid digit found in string\n")
        raise SystemExit(1)
    return str(int(value))


def get_value(args, i, opt, valname):
    if i+1 >= len(args):
        sys.exit(missing_value(opt))
    return args[i+1], i+2


def main_cli(argv):
    # subcommand help aliases
    if len(argv) >= 1 and argv[0] == 'help':
        if len(argv) >= 2 and argv[1] == 'build':
            sys.stdout.write(BUILD_HELP); return 0
        sys.stdout.write(HELP); return 0
    if len(argv) >= 1 and argv[0] == 'build':
        return build_cli(argv[1:])
    if any(a in ('--help','-h') for a in argv):
        sys.stdout.write(HELP); return 0
    if any(a in ('--version','-V') for a in argv):
        sys.stdout.write(VERSION + "\n"); return 0

    style = Style()
    output = None
    inline = False
    positionals = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '-s':
            inline = True; i += 1
        elif a in ('-o','--output'):
            if i+1 >= len(argv):
                sys.exit(missing_value(a))
            output = argv[i+1]; i += 2
        elif a == '--background':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.background = argv[i+1]; i += 2
        elif a == '--fill-color':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.fill_color = argv[i+1]; i += 2
        elif a == '--stroke-color':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.stroke_color = argv[i+1]; i += 2
        elif a == '--font-family':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.font_family = argv[i+1]; i += 2
        elif a == '--font-size':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            if argv[i+1].startswith('-'):
                return clap_unexpected(argv[i+1], "executable --font-size <font-size>")
            style.font_size = parse_font_size(argv[i+1]); i += 2
        elif a == '--stroke-width':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            # keep user's spelling if it parses
            parse_float_value('stroke-width', argv[i+1])
            style.stroke_width = argv[i+1]; i += 2
        elif a == '--scale':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            if argv[i+1].startswith('-'):
