                left_arrow = True; consumed_text.add((r,c)); h_consumed.add((r,c)); dash_start = c+1; run_char='-'
                elements.append(Element((r,c,1), polygon_arrow_left(style,c,r)))
            elif ch in '-_=':
                run_char = ch; dash_start = c
            else:
                c += 1; continue
            # collect a homogeneous run of -, _, or =
            j = dash_start
            while ch_at(grid,r,j) == run_char and (r,j) not in rect_perim:
                h_consumed.add((r,j)); consumed_text.add((r,j)); j += 1
            if j == dash_start:
                c += 1; continue
            right_arrow = False; right_marker = None; right_c = None
            if run_char == '-' and ch_at(grid,r,j) == '>':
                right_arrow = True; right_c = j; consumed_text.add((r,j)); h_consumed.add((r,j))
            elif run_char == '-' and ch_at(grid,r,j) in 'oO*':
                right_marker = ch_at(grid,r,j); right_c = j; consumed_text.add((r,j)); h_consumed.add((r,j))
