                x2 = j*8
                if left_plus: x1 = (dash_start-1)*8 + 4; consumed_text.add((r,dash_start-1))
                if right_plus: x2 = j*8 + 4; consumed_text.add((r,j))
                elements.append(Element((r,dash_start,3), line_el(style,x1,r*16+6,x2,r*16+6,"solid")))
                elements.append(Element((r,dash_start,4), line_el(style,x1,r*16+10,x2,r*16+10,"solid")))
            else:
