                    cls = "solid " + marker_class(start_marker)
                    elements.append(Element((r,start_c,1), line_el(style,rest_start,r*16+8,center,r*16+8,cls)))
                    plain_start = rest_start if start_marker in 'oO' else (start_c+1)*8
                elif left_arrow:
                    plain_start = (start_c+1)*8
