                if right_arrow:
                    plain_end = right_c*8
                    if plain_end != plain_start:
                        elements.append(Element((r,dash_start,3), line_el(style,plain_start,y,plain_end,y,"solid")))
                    elements.append(Element((r,right_c,5), polygon_arrow_right(style,right_c,r)))
                    c = right_c + 1
