                    if start_marker == '*' and right_marker == '*':
                        # The original leaves a small solid tail near filled-circle ends.
                        elements.append(Element((r,right_c,4), line_el(style,right_c*8,y,right_c*8+4,y,"solid")))
                    c = right_c + 1
