    # Vertical segments from | and + junctions. Build and merge by x coordinate.
    v_by_x = {}
    for r,line in enumerate(grid):
        for c,ch in enumerate(line):
            if (r,c) in rect_perim:
                continue
            x = c*8 + 4
            if ch == '|':
                consumed_text.add((r,c))
                v_by_x.setdefault(x, []).append((r*16, (r+1)*16, (r,c,2)))
            elif ch == '+':
                up = provides_v(ch_at(grid,r-1,c))
                down = provides_v(ch_at(grid,r+1,c))
                if up or down:
                    consumed_text.add((r,c))
