                elements.append(Element((r,c,2), f'  <path d="{d}" class="nofill"></path>'))

    # Remaining text, grouped horizontally through non-space characters.
    for r,line in enumerate(grid):
        c = 0
        while c < len(line):
            if (r,c) in consumed_text or line[c] in ' \t':
                c += 1; continue
            start = c
            chars = []
            while c < len(line) and (r,c) not in consumed_text and line[c] not in ' \t':
                chars.append(line[c]); c += 1
            if chars:
