def clap_unexpected(arg, usage="executable [FLAGS] [OPTIONS] [input] [SUBCOMMAND]"):
    sys.stderr.write(f"error: Found argument '{arg}' which wasn't expected, or isn't valid in this context\n\n")
    sys.stderr.write(f"USAGE:\n    {usage}\n\nFor more information try --help\n")
    return 1


def missing_value(opt):
    sys.stderr.write(f"error: The argument '{opt} <{opt.lstrip('-')}>' requires a value but none was supplied\n\n")
    sys.stderr.write(f"USAGE:\n    executable {opt} <{opt.lstrip('-')}>\n\nFor more information try --help\n")
    return 1


def parse_float_value(name, value):
    try:
        return float(value)
    except Exception:
        sys.stderr.write(f"Illegal value for argument {name}: invalid float literal\n")
        raise SystemExit(1)


def parse_font_size(value):
    if not value.isdigit():
        # Rust's parse::<usize> gives this for alphabetic/decimal inputs; clap handles - separately.
        sys.stderr.write("Illegal value for argument font-size: invalid digit found in string\n")
        raise SystemExit(1)
    return str(int(value))


def get_value(args, i, opt, valname):
    if i+1 >= len(args):
        sys.exit(missing_value(opt))
    return args[i+1], i+2


def main_cli(argv):
    # subcommand help aliases
    if len(argv) >= 1 and argv[0] == 'help':
        if len(argv) >= 2 and argv[1] == 'build':
            sys.stdout.write(BUILD_HELP); return 0
        sys.stdout.write(HELP); return 0
    if len(argv) >= 1 and argv[0] == 'build':
        return build_cli(argv[1:])
    if any(a in ('--help','-h') for a in argv):
        sys.stdout.write(HELP); return 0
    if any(a in ('--version','-V') for a in argv):
        sys.stdout.write(VERSION + "\n"); return 0

    style = Style()
    output = None
    inline = False
    positionals = []
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '-s':
            inline = True; i += 1
        elif a in ('-o','--output'):
            if i+1 >= len(argv):
                sys.exit(missing_value(a))
            output = argv[i+1]; i += 2
        elif a == '--background':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.background = argv[i+1]; i += 2
        elif a == '--fill-color':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.fill_color = argv[i+1]; i += 2
        elif a == '--stroke-color':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.stroke_color = argv[i+1]; i += 2
        elif a == '--font-family':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            style.font_family = argv[i+1]; i += 2
        elif a == '--font-size':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            if argv[i+1].startswith('-'):
                return clap_unexpected(argv[i+1], "executable --font-size <font-size>")
            style.font_size = parse_font_size(argv[i+1]); i += 2
        elif a == '--stroke-width':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            # keep user's spelling if it parses
            parse_float_value('stroke-width', argv[i+1])
            style.stroke_width = argv[i+1]; i += 2
        elif a == '--scale':
            if i+1 >= len(argv): sys.exit(missing_value(a))
            if argv[i+1].startswith('-'):
                return clap_unexpected(argv[i+1], "executable --scale <scale>")
            style.scale = parse_float_value('scale', argv[i+1]); i += 2
        elif a.startswith('--') or (a.startswith('-') and a != '-'):
            return clap_unexpected(a)
        else:
            positionals.append(a); i += 1
    if len(positionals) > 1:
        return clap_unexpected(positionals[1])

    if inline:
        if not positionals:
            # The real program panics due to unwrap(); reproduce the externally visible shape enough.
            sys.stderr.write("\nthread 'main' panicked at crates/svgbob_cli/src/main.rs:84:38:\n")
            sys.stderr.write("called `Option::unwrap()` on a `None` value\n")
            sys.stderr.write("note: run with `RUST_BACKTRACE=1` environment variable to display a backtrace\n")
            return 101
        data = positionals[0]
    else:
        if positionals:
            path = positionals[0]
            try:
                with open(path, 'r', encoding='utf-8') as f:
                    data = f.read()
            except OSError as e:
                sys.stderr.write(f"Failed to open input file {path}: {e.strerror} (os error {e.errno})\n")
                return 1
        else:
            data = sys.stdin.read()
    svg = render_svg(data, style)
    if output is not None and output != 'STDOUT':
        with open(output, 'w', encoding='utf-8') as f:
            f.write(svg)
    else:
        sys.stdout.write(svg)
    return 0


def build_cli(argv):
    if any(a in ('--help','-h') for a in argv):
        sys.stdout.write(BUILD_HELP); return 0
    if any(a in ('--version','-V') for a in argv):
        sys.stdout.write(BUILD_VERSION + "\n"); return 0
    inp = ""
    outdir = ""
    i = 0
    while i < len(argv):
        a = argv[i]
        if a in ('-i','--input'):
            if i+1 >= len(argv):
                # close enough for build
                sys.stderr.write("error: The argument '--input <input>' requires a value but none was supplied\n")
                return 1
            inp = argv[i+1]; i += 2
        elif a in ('-o','--outdir'):
            if i+1 >= len(argv):
                sys.stderr.write("error: The argument '--outdir <outdir>' requires a value but none was supplied\n")
                return 1
            outdir = argv[i+1]; i += 2
        else:
            return clap_unexpected(a, "executable build [OPTIONS]")
    dirname = os.path.dirname(inp)
    if dirname == "" and ("/" not in inp):
        dirname = "." if inp else ""
    if not dirname or not os.path.isdir(dirname):
        sys.stdout.write(f"[Error]: No such dir name is {dirname} !\n")
        return 1
    matches = sorted(glob.glob(inp))
    for p in matches:
        base = os.path.splitext(os.path.basename(p))[0] + ".svg"
        od = outdir if outdir else os.path.dirname(p)
        if od:
            os.makedirs(od, exist_ok=True)
        dest = os.path.join(od, base) if od else base
        try:
            with open(p, 'r', encoding='utf-8') as f:
                data = f.read()
            with open(dest, 'w', encoding='utf-8') as f:
                f.write(render_svg(data, Style()))
            sys.stdout.write(f"{p} => {dest}\n")
        except OSError:
            pass
    return 1

if __name__ == '__main__':
    sys.exit(main_cli(sys.argv[1:]))
